  const onRail = (x, z) => (z === z0 && railed("north")) || (z === z1 && railed("south")) || (x === x0 && railed("west")) || (x === x1 && railed("east"));
  for (let x = x0; x <= x1; x++) for (let z = z0; z <= z1; z++) {
    if (!onRail(x, z) || skip(x, z)) continue;
